package com.cappleapple.astralrepository.platform.client.event;
public final class RegisterClientReloadListenersEvent {public void registerReloadListener(net.minecraft.server.packs.resources.ResourceManagerReloadListener listener){net.fabricmc.fabric.api.resource.ResourceManagerHelper.get(net.minecraft.server.packs.PackType.CLIENT_RESOURCES).registerReloadListener(new net.fabricmc.fabric.api.resource.SimpleSynchronousResourceReloadListener(){public net.minecraft.resources.ResourceLocation getFabricId(){return net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("astral_repository","client_resources");}public void onResourceManagerReload(net.minecraft.server.packs.resources.ResourceManager manager){listener.onResourceManagerReload(manager);}});}}
